#!/usr/bin/env node
// Graysmith Labs guard hook for Claude Code.
//
// PreToolUse (Bash): blocks commits not authored as Ramsey, attribution
// trailers, claude/ branches, generated by lines in pull requests, and Google
// test ad unit IDs headed into production code.
// PostToolUse (Edit, Write, MultiEdit): flags edits to files synced from HQ
// (.claude/synced.json), checks store.config.json against App
// Store limits, the no dashes rule and its screenshot files, checks screenshot
// captions in scenes.json for price, free and trial wording, and checks screen
// code against the design rules from the Drift 1.18.0 refresh (theme tokens
// instead of raw colors, no placeholder ad text, no Alert.alert), checks the
// Android pieces (play.config.json limits and Play metadata policy, the
// com.graysmithlabs package rule and per platform AdMob app IDs in app.json,
// App Store links with no Android branch in app code), and hands problems
// back to Claude.
//
// Exit 2 with a message on stderr blocks the call (Pre) or reports back (Post).
// Any internal error exits 0, so a broken hook never stops work.

import { execSync } from 'node:child_process';
import { readFileSync, existsSync } from 'node:fs';
import { basename, dirname, join, relative } from 'node:path';

const OWNER_NAME = 'Ramsey Graysmith';
const OWNER_EMAIL = 'smith.s.ramsey@gmail.com';
const TEST_PUBLISHER = 'ca-app-pub-3940256099942544';

function block(msg) {
  process.stderr.write(msg.trim() + '\n');
  process.exit(2);
}

function sh(cmd, cwd) {
  try {
    return execSync(cmd, { cwd, stdio: ['ignore', 'pipe', 'ignore'] }).toString().trim();
  } catch {
    return '';
  }
}

// Prose dash check that ignores URLs and email addresses.
export function proseDashes(text) {
  const stripped = String(text)
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/\S+@\S+/g, ' ');
  const hits = [];
  for (const line of stripped.split('\n')) {
    if (/[‐-―−]/.test(line) || /(^|[\s(])-(\s|$)|\w-\w/.test(line)) hits.push(line.trim().slice(0, 80));
  }
  return hits;
}

export function lintStoreConfig(json) {
  const problems = [];
  const info = json?.apple?.info || {};
  const LIMITS = { title: 30, subtitle: 30, promoText: 170, description: 4000, releaseNotes: 4000 };
  for (const [locale, l] of Object.entries(info)) {
    for (const [field, max] of Object.entries(LIMITS)) {
      if (typeof l[field] !== 'string') continue;
      if (l[field].length > max) problems.push(`${locale} ${field} is ${l[field].length} characters, limit ${max}`);
      for (const hit of proseDashes(l[field])) problems.push(`${locale} ${field} has a dash: "${hit}"`);
    }
    if (Array.isArray(l.keywords)) {
      const joined = l.keywords.join(',');
      if (joined.length > 100) problems.push(`${locale} keywords are ${joined.length} characters joined, limit 100`);
      const named = `${l.title || ''} ${l.subtitle || ''}`.toLowerCase();
      for (const k of l.keywords) {
        if (!/\s/.test(k.trim()) && named.split(/[^a-z0-9]+/).includes(k.toLowerCase()))
          problems.push(`${locale} keyword "${k}" already appears in the title or subtitle, so it wastes space`);
        if (/^(app|free)$/i.test(k)) problems.push(`${locale} keyword "${k}" is ignored by Apple`);
      }
    }
  }
  return problems;
}

// Guideline 2.3.7: screenshots and their captions may not mention price, free,
// trials or discounts. Drift 1.18.0 (54) was rejected on Oct 18 2026 for a
// paywall frame captioned "Your first week is free", and SayBright had the same
// frame. Price and trial copy belongs in the description and promo text only.
export const PRICE_WORDS =
  /\bfree\b|\btrial\b|\bprice|\bdiscount|\bsale\b|\bdeal\b|[$€£¥]\s?\d|\d+\s?% off|\/\s?(mo|month|yr|year|week)\b|per (month|year|week)/i;
const PAYWALL_PATH = /\/(paywall|premium|pricing|subscribe)\b/i;

// scenes.json (make.py) and captions.json (compose.py) list the store frames.
export function lintScenes(json) {
  const problems = [];
  for (const s of [...(json?.scenes || []), ...(json?.shots || [])]) {
    for (const field of ['title', 'subtitle']) {
      const hit = s?.[field] && PRICE_WORDS.exec(s[field]);
      if (hit) problems.push(`${s.name} ${field} "${s[field]}" mentions "${hit[0]}"; captions may not reference price, free or trials (Guideline 2.3.7)`);
    }
    if (s?.path && PAYWALL_PATH.test(s.path))
      problems.push(`${s.name} captures ${s.path}; the paywall belongs only in the "paywall" entry for subscription review, never in the listing`);
  }
  return problems;
}

// App Store screenshot slots and the pixel sizes Apple accepts for each.
export const SCREENSHOT_SLOTS = {
  APP_IPHONE_67: [[1320, 2868], [1290, 2796]],
  APP_IPHONE_65: [[1242, 2688], [1284, 2778]],
  APP_IPHONE_61: [[1206, 2622], [1179, 2556]],
  APP_IPAD_PRO_3GEN_129: [[2064, 2752], [2048, 2732]],
};

// Width and height from a PNG header, or null for anything else.
export function pngSize(buf) {
  if (!buf || buf.length < 24 || buf.readUInt32BE(0) !== 0x89504e47) return null;
  return [buf.readUInt32BE(16), buf.readUInt32BE(20)];
}

export function lintScreenshots(json, root, appJson) {
  const problems = [];
  for (const [locale, info] of Object.entries(json?.apple?.info || {})) {
    const shots = info.screenshots;
    if (!shots) continue;
    for (const [slot, files] of Object.entries(shots)) {
      const sizes = SCREENSHOT_SLOTS[slot];
      for (const f of files || []) {
        if (/paywall|premium|pricing/i.test(basename(f)))
          problems.push(`${locale} ${slot}: ${f} looks like a paywall frame; listing screenshots may not show prices or trials (Guideline 2.3.7)`);
        const path = join(root, f);
        if (!existsSync(path)) {
          problems.push(`${locale} ${slot}: ${f} does not exist`);
          continue;
        }
        const size = pngSize(readFileSync(path));
        if (sizes && size && !sizes.some(([w, h]) => w === size[0] && h === size[1]))
          problems.push(`${locale} ${slot}: ${f} is ${size[0]} x ${size[1]}, the slot takes ${sizes.map((s) => s.join(' x ')).join(' or ')}`);
      }
    }
    if (appJson?.expo?.ios?.supportsTablet && Object.keys(shots).length && !shots.APP_IPAD_PRO_3GEN_129)
      problems.push(`${locale}: the app supports iPad but lists no APP_IPAD_PRO_3GEN_129 screenshots (bun run screenshots makes them)`);
  }
  return problems;
}

// Design rules for screen code, active once the app has src/theme/colors.ts.
const SCREEN_FILE = /(^|\/)src\/(app|components)\/.+\.tsx$/;
const SCREEN_EXEMPT = /\/components\/art\/|\.web\.tsx$|\/\+html\.tsx$|AnimatedSplashScreen/;
export function lintScreenCode(text, file, hasTheme) {
  if (!SCREEN_FILE.test(file) || SCREEN_EXEMPT.test(file)) return [];
  const problems = [];
  const code = String(text)
    .split('\n')
    .filter((l) => !/^\s*(\/\/|\*|\/\*)/.test(l))
    .join('\n');
  if (hasTheme) {
    const hex = [...code.matchAll(/['"`](#[0-9a-fA-F]{3,8})['"`]/g)]
      .map((m) => m[1])
      .filter((h) => !/^#(fff|ffffff|000|000000)$/i.test(h));
    if (hex.length)
      problems.push(`raw colors ${[...new Set(hex)].slice(0, 5).join(', ')}: add them to src/theme/colors.ts and use C tokens`);
  }
  if (/>[^<{]*(Loading ad|Ad unavailable|lorem ipsum)/i.test(code))
    problems.push('placeholder text users would see ("Loading ad", "Ad unavailable", lorem); render nothing instead');
  if (/Alert\.alert\(/.test(code)) problems.push('Alert.alert: use an inline message or a custom modal');
  if (/style=\{\s*\(\s*\{\s*pressed\s*\}\s*\)\s*=>/.test(code))
    problems.push('Pressable style function (style={({ pressed }) => ...}): NativeWind drops it on iOS and the layout collapses; use static styles with a pressedStyle (Drift src/components/Tap.tsx)');
  return problems;
}

// Google Play listing (play.config.json, pushed by scripts/android/play-listing.mjs).
// Same limits as the Play Console, the no dashes rule, Play's ban on promo and
// price claims in the title and short description, and no mention of iOS.
export function lintPlayConfig(json) {
  const problems = [];
  const LIMITS = { title: 30, shortDescription: 80, fullDescription: 4000 };
  for (const [lang, l] of Object.entries(json?.listings || {})) {
    for (const [field, max] of Object.entries(LIMITS)) {
      if (typeof l[field] !== 'string') continue;
      if (l[field].length > max) problems.push(`${lang} ${field} is ${l[field].length} characters, limit ${max}`);
      for (const hit of proseDashes(l[field])) problems.push(`${lang} ${field} has a dash: "${hit}"`);
    }
    for (const field of ['title', 'shortDescription']) {
      const hit = l[field] && /\bfree\b|\btrial\b|\bdiscount|\bsale\b|\bbest\b|#1|\btop\b|[$€£¥]\s?\d|\d+\s?% off/i.exec(l[field]);
      if (hit) problems.push(`${lang} ${field} says "${hit[0]}"; Play bans price, ranking and promo claims there`);
    }
    if (/\b(iphone|ipad|app store|ios)\b/i.test(`${l.title} ${l.shortDescription} ${l.fullDescription}`))
      problems.push(`${lang} mentions iPhone, iPad, iOS or the App Store; Play rejects that`);
  }
  return problems;
}

// Android parts of app.json: the permanent package name and per platform AdMob app IDs.
export function lintAndroidAppJson(json) {
  const problems = [];
  const expo = json?.expo || {};
  const pkg = expo.android?.package;
  if (pkg && !/^com\.graysmithlabs\.[a-z][a-z0-9]*$/.test(pkg))
    problems.push(`android.package ${pkg}: Graysmith Labs apps use com.graysmithlabs.<app>, and it can never change once on Play`);
  for (const p of expo.plugins || []) {
    if (!Array.isArray(p) || p[0] !== 'react-native-google-mobile-ads') continue;
    const { androidAppId, iosAppId } = p[1] || {};
    if (androidAppId && androidAppId === iosAppId)
      problems.push('react-native-google-mobile-ads androidAppId equals iosAppId; AdMob app IDs are per platform, so Android would serve nothing');
  }
  return problems;
}

// App Store links in app code with no Android branch send Android users to the App Store.
const APP_CODE = /(^|\/)(src|app|components|hooks|utils|contexts|lib)\/.+\.[jt]sx?$/;
export function lintStoreLinks(text, file) {
  if (!APP_CODE.test(file) || /\.(ios|web|test|spec)\.[jt]sx?$/.test(file) || /android-ok/.test(text)) return [];
  const code = String(text).replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:])\/\/.*$/gm, '$1');
  if (/apps\.apple\.com|itms-apps:/.test(code) && !/Platform\.(OS|select)|storeLinks|stores['"]/.test(code))
    return ['App Store URL with no Android branch; use src/lib/stores.ts (listingUrl, openReview, openManageSubscriptions) so Android users land on Google Play'];
  return [];
}

// Files synced from HQ (listed in the repo's .claude/synced.json) are edited in
// HQ, not here; the next sync would overwrite an edit made in the repo.
// Paywall events must name where the paywall was opened, or the nightly
// Paywalls table cannot tell entry points apart (HQ docs/paywalls.md).
export function lintPaywallEvents(text) {
  const problems = [];
  const re = /track\(\s*['"](paywall_view|paywall_close|trial_start|purchase)['"]\s*(?:,\s*(\{[^}]*\}))?\s*\)/g;
  let m;
  while ((m = re.exec(text))) {
    if (!/\bsource\b/.test(m[2] || ''))
      problems.push(`track('${m[1]}') at line ${text.slice(0, m.index).split('\n').length} has no source; pass { source, paywall_version: PAYWALL_VERSION }`);
  }
  return problems;
}

export function syncedSource(file) {
  let dir = dirname(file);
  for (let i = 0; i < 12 && dir && dir !== dirname(dir); i++, dir = dirname(dir)) {
    const list = join(dir, '.claude', 'synced.json');
    if (!existsSync(list)) continue;
    try {
      const files = JSON.parse(readFileSync(list, 'utf8')).files || {};
      return files[relative(dir, file)] || null;
    } catch {
      return null;
    }
  }
  return null;
}

export function checkCommand(cmd, cwd) {
  const isCommit = /\bgit\b[^;&|]*\bcommit\b/.test(cmd);
  const branch = /\bgit\b[^;&|]*\b(checkout\s+-b|switch\s+-c|branch|push)\b[^;&|]*\bclaude\//.test(cmd);
  if (branch) return 'Branch names starting with claude/ are not allowed. Use growth/<topic>.';
  // Over the air updates go through the HQ gate (Nov 12 2026): it checks the smoke
  // ran on this sha, the paywall doctor, tsc and that no RevenueCat test key rides
  // along (a release build or update with a test_ key makes the app quit on launch).
  if (/\beas(-cli)?\s+update\b/.test(cmd) && !/ota_ready\.sh/.test(cmd) && !/\b--help\b|\bupdate:(list|view|rollback)\b/.test(cmd))
    return 'Publish over the air updates with: bash ~/Documents/Github/graysmith_labs_agent/scripts/ota_ready.sh <app dir> "<message>" (it gates the smoke sha, the paywall doctor, tsc and RevenueCat test keys, then publishes).';
  if (/REVENUECAT_TEST_KEY=/.test(cmd) && /\beas(-cli)?\s+(build|update)\b|\bexpo\s+export\b|build:(testflight|play)/.test(cmd))
    return 'A RevenueCat test key must never reach a store build or update: RevenueCat closes release builds that carry one. Test keys are for Debug builds only (HQ scripts/paywall_preview.sh).';
  if (/Co-Authored-By|Claude-Session/i.test(cmd))
    return 'Remove the Co-Authored-By and Claude-Session trailers. Commits are Ramsey\'s alone.';
  if (/\bgh\s+pr\s+(create|edit)\b/.test(cmd) && /Generated with|claude\.com\/claude-code|claude\.ai\/code/i.test(cmd))
    return 'Remove the generated by line and Claude links from the pull request body.';
  if (isCommit) {
    const author = /--author[= ]["']?([^"']+)/.exec(cmd);
    if (author && !author[1].includes(OWNER_EMAIL)) return `Commits must be authored as ${OWNER_NAME} <${OWNER_EMAIL}>.`;
    const fileArg = /\s(?:-F|--file)[= ]["']?([^\s"']+)/.exec(cmd);
    if (fileArg && existsSync(fileArg[1]) && /Co-Authored-By|Claude-Session/i.test(readFileSync(fileArg[1], 'utf8')))
      return 'The commit message file has attribution trailers. Remove them.';
    const email = sh('git config user.email', cwd);
    const name = sh('git config user.name', cwd);
    if (email && (email !== OWNER_EMAIL || name !== OWNER_NAME))
      return `Git identity is ${name} <${email}>. Run: git config user.name "${OWNER_NAME}" && git config user.email "${OWNER_EMAIL}"`;
    // Only app code can ship a test ID. Docs, tests and this hook mention it on purpose.
    const CODE = /\.(m?[jt]sx?|json)$/;
    const SKIP = /(^|\/)(\.claude|__tests__|node_modules)\/|\.(test|spec)\./;
    const diff = sh('git diff HEAD -U0 --no-color', cwd);
    const added = [];
    let current = '';
    for (const l of diff.split('\n')) {
      if (l.startsWith('+++ ')) current = l.slice(6);
      else if (l.startsWith('+') && CODE.test(current) && !SKIP.test(current)) added.push(l);
    }
    // New files are not in the diff yet when the command is `git add -A && git commit`.
    for (const f of sh('git ls-files --others --exclude-standard', cwd).split('\n').filter(Boolean)) {
      if (!CODE.test(f) || SKIP.test(f)) continue;
      try {
        added.push(...readFileSync(`${cwd}/${f}`, 'utf8').split('\n').map((l) => '+' + l));
      } catch {}
    }
    const bad = added.filter((l) => l.includes(TEST_PUBLISHER) && !/__DEV__|TestIds|isDev|DEV/.test(l));
    if (bad.length)
      return `A Google test ad unit ID is being added outside a __DEV__ guard:\n${bad.slice(0, 3).join('\n')}\nGate it on __DEV__ or use the live unit ID. Shipping test IDs earns nothing.`;
  }
  return '';
}

async function main() {
  let raw = '';
  for await (const chunk of process.stdin) raw += chunk;
  const input = JSON.parse(raw || '{}');
  const event = input.hook_event_name;
  const tool = input.tool_name;
  const cwd = input.cwd || process.cwd();

  if (event === 'PreToolUse' && tool === 'Bash') {
    const msg = checkCommand(String(input.tool_input?.command || ''), cwd);
    if (msg) block(msg);
  }

  if (event === 'PostToolUse' && /^(Edit|Write|MultiEdit)$/.test(tool)) {
    const file = input.tool_input?.file_path || '';
    const source = file && syncedSource(file);
    if (source)
      block(
        `${basename(file)} is synced from HQ (graysmith_labs_agent/${source}), so this edit will be overwritten by the next sync. ` +
          `Make the change in that HQ file instead, then run: node scripts/claude_assets.mjs sync <this repo> from HQ. Revert this file here.`,
      );
    if (basename(file) === 'eas.json' && existsSync(file) && /REVENUECAT_TEST_KEY/.test(readFileSync(file, 'utf8')))
      block('eas.json now carries a RevenueCat test key. Remove it: RevenueCat closes release builds (simulator builds included) that carry a test_ key. Test keys live in HQ data/revenuecat-test-keys.json and are used only by scripts/paywall_preview.sh in Debug builds.');
    if (basename(file) === 'store.config.json' && existsSync(file)) {
      let json;
      try {
        json = JSON.parse(readFileSync(file, 'utf8'));
      } catch (e) {
        block(`store.config.json is not valid JSON: ${e.message}`);
      }
      let appJson = null;
      try {
        appJson = JSON.parse(readFileSync(join(dirname(file), 'app.json'), 'utf8'));
      } catch {}
      const problems = [...lintStoreConfig(json), ...lintScreenshots(json, dirname(file), appJson)];
      if (problems.length) block(`store.config.json needs fixes before store:push:\n* ${problems.join('\n* ')}`);
    }
    if (basename(file) === 'play.config.json' && existsSync(file)) {
      let json;
      try {
        json = JSON.parse(readFileSync(file, 'utf8'));
      } catch (e) {
        block(`play.config.json is not valid JSON: ${e.message}`);
      }
      const problems = lintPlayConfig(json);
      if (problems.length) block(`play.config.json needs fixes before play:push:\n* ${problems.join('\n* ')}`);
    }
    if (basename(file) === 'app.json' && existsSync(file)) {
      let json = null;
      try {
        json = JSON.parse(readFileSync(file, 'utf8'));
      } catch {}
      const problems = lintAndroidAppJson(json);
      if (problems.length) block(`app.json would break Android:\n* ${problems.join('\n* ')}`);
    }
    if (/\.[jt]sx?$/.test(file) && existsSync(file)) {
      const root = input.cwd || cwd;
      const rel = relative(root, file);
      const text = readFileSync(file, 'utf8');
      const problems = [...lintStoreLinks(text, rel.startsWith('..') ? file : rel), ...lintPaywallEvents(text)];
      if (problems.length) block(`${basename(file)}:\n* ${problems.join('\n* ')}`);
    }
    if (/^(scenes|captions)(\.example)?\.json$/.test(basename(file)) && existsSync(file)) {
      let scenes = null;
      try {
        scenes = JSON.parse(readFileSync(file, 'utf8'));
      } catch {}
      const problems = lintScenes(scenes);
      if (problems.length) block(`${basename(file)} would break App Store Guideline 2.3.7:\n* ${problems.join('\n* ')}`);
    }
    if (/\.tsx$/.test(file) && existsSync(file)) {
      const root = input.cwd || cwd;
      const rel = relative(root, file);
      const problems = lintScreenCode(readFileSync(file, 'utf8'), rel.startsWith('..') ? file : rel, existsSync(join(root, 'src/theme/colors.ts')));
      if (problems.length) block(`${basename(file)} breaks the design rules (see the ui-refresh skill):\n* ${problems.join('\n* ')}`);
    }
  }
  process.exit(0);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch(() => process.exit(0));
}
